import React, { useState } from "react";
import { logout, useOpenbase } from "../../../ppm/openbase/openbase";

const DEV_ENDPOINT = "https://images--salt-river-roofing.makethemcall.workers.dev/api/dev";

export default function TestAuthPanel() {
  const [output, setOutput] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const { loading: authLoading, openbase: authed } = useOpenbase();

  if (authLoading) return "Verifying session...";

  const handleTestEnvs = async () => {
    setLoading(true);
    setOutput(null);

    try {
      const res = await fetch(DEV_ENDPOINT, {
        method: "GET",
      });

      const data = await safeJson(res);

      setOutput({
        step: "test_envs",
        endpoint: DEV_ENDPOINT,
        data,
      });
    } catch (err: any) {
      setOutput({
        step: "test_envs",
        success: false,
        error: err?.message || err,
      });
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();

    setOutput({
      success: true,
      data: "logged out",
    });
  };

  return (
    <div style={{ width: "100%", minHeight: "100vh", background: "#ffffff", padding: 20, boxSizing: "border-box", fontFamily: "system-ui, Arial" }}>
      <div style={{ width: "min(900px, 100%)", margin: "0 auto", border: "1px solid #ddd", borderRadius: 12, padding: 18, boxShadow: "0 10px 30px rgba(0,0,0,0.06)", background: "#fff" }}>
        <h2 style={{ marginTop: 0, marginBottom: 12 }}>Auth Env Test Panel</h2>

        <div style={{ marginBottom: 18, padding: 14, border: "1px solid #eee", borderRadius: 10, background: "#fafafa", fontSize: 13 }}>
          <div style={{ fontWeight: 700, marginBottom: 8 }}>Active Login Status</div>

          {authed ? (
            <div style={{ color: "#137333" }}>Active login found</div>
          ) : (
            <div style={{ color: "#b3261e" }}>No active login found</div>
          )}
        </div>

        <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
          {authed && (
            <Button onClick={handleTestEnvs} disabled={loading}>
              Test Envs
            </Button>
          )}

          <Button onClick={handleLogout} disabled={loading}>
            Logout
          </Button>
        </div>

        <div style={{ marginTop: 18, padding: 14, border: "1px solid #eee", borderRadius: 10, background: "#fafafa", fontSize: 13, minHeight: 120, whiteSpace: "pre-wrap", overflowX: "auto" }}>
          {loading ? "Running..." : output ? JSON.stringify(output, null, 2) : "No output yet"}
        </div>
      </div>
    </div>
  );
}

async function safeJson(res: Response) {
  const text = await res.text();

  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return {
      status: res.status,
      ok: res.ok,
      body: text,
    };
  }
}

const Button = ({ children, onClick, disabled }: any) => (
  <button
    onClick={onClick}
    disabled={disabled}
    style={{
      border: "1px solid #ddd",
      background: disabled ? "#f4f4f4" : "#fff",
      color: disabled ? "#999" : "#111",
      borderRadius: 8,
      padding: "8px 12px",
      cursor: disabled ? "not-allowed" : "pointer",
      fontSize: 13,
    }}
  >
    {children}
  </button>
);